from collections import Counter


def transform(grid):
    """Continue a strongly established period-two row pattern at the right."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if w < 10 or row[0] == row[1]:
            continue
        motif = (row[0], row[1])
        prefix = 2
        while prefix < w and row[prefix] == motif[prefix % 2]:
            prefix += 1
        if prefix < 10 or bg not in motif:
            continue
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        for c in range(last + 1, w):
            if motif[c % 2] != bg:
                out[r][c] = 1
    return out

