    # Treat separated horizontal clusters as copies of a motif; the cluster
    # whose colored pattern stops earliest is the incomplete copy.
    active = [any(v != bg for v in row) for row in grid]
    groups = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        a = r
        while r + 1 < h and active[r + 1]:
            r += 1
        b = r
        edge = max((c for rr in range(a, b + 1) for c, v in enumerate(grid[rr]) if v != bg), default=-1)
        groups.append((a, b, edge))
        r += 1
    if len(groups) < 2:
        return out
    target = min(groups, key=lambda x: x[2])
    ta, tb, edge = target

    def extrapolate_from_source(src, offset, start, end):
        """Get a source value at source-column=target-column+offset, extending its tail."""
        sw = len(src)
        for c in range(start, end):
            sc = c + offset
            if 0 <= sc < sw:
                val = src[sc]
            else:
                # Extend the source's terminal run (or its short period).
                if sc >= sw:
                    tail = src[max(0, sw - 6):]
                    val = tail[(sc - (sw - len(tail))) % len(tail)]
                else:
                    val = bg
            if val != bg:
                out[current_row][c] = 1

    for current_row in range(ta, tb + 1):
        row = grid[current_row]
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == w - 1:
            continue
        # Find the longest exact suffix match against another motif row, allowing
        # small horizontal shifts (the copies may start at different columns).
        best = None
        for srcrow in range(h):
            if srcrow == current_row:
                continue
            if not active[srcrow]:
                continue
            src = grid[srcrow]
            for off in range(-w + 1, w):
                nmatch = 0
                c = last
                while c >= 0 and c + off >= 0 and c + off < w and row[c] == src[c + off]:
                    nmatch += 1
                    c -= 1
                if nmatch >= 3 and (best is None or nmatch > best[0]):
                    best = (nmatch, srcrow, off)
        if best is not None:
            _, srcrow, off = best
            current_row_saved = current_row
            # Complete from the matching row, using its periodic terminal motif if
            # the matching row itself ends before the target grid edge.
            src = grid[srcrow]
            for c in range(last + 1, w):
                sc = c + off
                if 0 <= sc < w:
                    val = src[sc]
                elif sc >= w:
                    # The right edge of these source objects is typically a solid
                    # repeated run; continue that run where possible.
                    tail = src[max(0, w - 6):]
                    val = tail[(sc - (w - len(tail))) % len(tail)]
                else:
                    val = bg
                if val != bg:
                    out[current_row][c] = 1
            continue

        # No matching copy: extrapolate the shortest recent period, including the
        # first blank separator cell so that gaps in the motif stay blank.
        prefix_end = min(w, last + 2)
        seq = row[:prefix_end]
        maxp = min(8, max(1, len(seq) // 2))
        scores = []
        for p in range(1, maxp + 1):
